 /**
  * NotificationPreferenceForm Component
  * A React-style component for selecting notification preferences.
  */
 function NotificationPreferenceForm() {
   const options = [
     { id: 'email', label: 'Email', value: 'email' },
     { id: 'sms', label: 'SMS', value: 'sms' },
     { id: 'push', label: 'Push Notifications', value: 'push' }
   ];

   return `
     <form id="notification-form" class="card" novalidate>
       <h1>Notification Settings</h1>

       <div class="form-field">
         <fieldset aria-describedby="preference-help">
           <legend>How do you prefer to receive notifications? <span aria-hidden="true" style="color: #d93025;">*</span></legend>
           <p id="preference-help" class="help-text">Please select one option.</p>
           <p id="preference-error" class="error-text" style="display: none;" role="alert"></p>

           <div class="radio-group">
             ${options.map(option => `
               <div class="radio-option">
                 <input 
                   type="radio" 
                   id="${option.id}" 
                   name="notification-preference" 
                   value="${option.value}"
                   required
                 >
                 <label for="${option.id}">${option.label}</label>
               </div>
             `).join('')}
           </div>
         </fieldset>
       </div>

       <button type="submit">Save Preferences</button>
     </form>
   `;
 }

 // Simple "render" function
 function render() {
   const root = document.getElementById('root');
   if (root) {
     root.innerHTML = NotificationPreferenceForm();

     const form = document.getElementById('notification-form');
     const fieldset = form.querySelector('fieldset');
     const errorDisplay = document.getElementById('preference-error');
     const radioInputs = form.querySelectorAll('input[name="notification-preference"]');

     const showError = (message) => {
       errorDisplay.textContent = `Error: ${message}`;
       errorDisplay.style.display = 'block';
       fieldset.setAttribute('aria-describedby', 'preference-help preference-error');
       radioInputs.forEach(input => input.setAttribute('aria-invalid', 'true'));
     };

     const clearError = () => {
       errorDisplay.style.display = 'none';
       fieldset.setAttribute('aria-describedby', 'preference-help');
       radioInputs.forEach(input => input.removeAttribute('aria-invalid'));
     };

     // Add event listener for form submission
     form.addEventListener('submit', (e) => {
       e.preventDefault();
       const formData = new FormData(form);
       const preference = formData.get('notification-preference');

       if (!preference) {
         showError('Please select a notification preference.');
         // Focus the first radio button on error
         radioInputs[0].focus();
         return;
       }

       clearError();
       console.log('Selected preference:', preference);
       alert(`Preference saved: ${preference}`);
     });

     // Clear error when user makes a selection
     radioInputs.forEach(input => {
       input.addEventListener('change', clearError);
     });
   }
 }

 // Initialize on DOM load
 document.addEventListener('DOMContentLoaded', render);

